function validate([moves]) {
  if (typeof moves !== 'string') return 'moves must be a string.';
  if (moves.length < 1 || moves.length > 20000) return 'moves needs 1 to 20000 characters.';
  if (!/^[UDLR]+$/.test(moves)) return "moves may only contain 'U', 'D', 'L' and 'R'.";
  return null;
}

