function judgeCircle(moves) {
  let x = 0;
  let y = 0;

  for (const move of moves) {
    if (move === 'U') {
      y++;
    } else if (move === 'D') {
      y--;
    } else if (move === 'L') {
      x--;
    } else {
      x++;
    }
  }
  return x === 0 && y === 0;
}

