function generate(rand, size) {
  const letters = 'UDLR';
  const shuffle = (list) => {
    for (let i = list.length - 1; i > 0; i--) {
      const j = Math.floor(rand() * (i + 1));
      [list[i], list[j]] = [list[j], list[i]];
    }
    return list;
  };
  const target = size === 'large' ? 9000 + Math.floor(rand() * 1001) : 1 + Math.floor(rand() * 10);
  // Half of the inputs are built from matched pairs so that the answer is true often enough.
  if (rand() < 0.5 && target >= 2) {
    const pairs = Math.floor(target / 2);
    const steps = [];
    for (let i = 0; i < pairs; i++) {
      if (rand() < 0.5) steps.push('U', 'D');
      else steps.push('L', 'R');
    }
    // Occasionally swap one step so that the path misses the origin by a little.
    if (rand() < 0.3) steps[Math.floor(rand() * steps.length)] = letters[Math.floor(rand() * 4)];
    return [shuffle(steps).join('')];
  }
  let moves = '';
  for (let i = 0; i < target; i++) moves += letters[Math.floor(rand() * 4)];
  return [moves];
}
